action.code:
if (binfo == nullptr) {
    return 0;
}

/*
 * The bitmap_info_t structure (as seen in BITMAP_INFO_INITIALIZER) 
 * stores the cumulative number of groups required for each level 
 * in its 'levels' array. The total number of groups needed for 
 * the bitmap is the value stored for the highest level used.
 */
size_t total_groups = binfo->levels[binfo->nlevels - 1];
return total_groups * sizeof(bitmap_t);

